import os
import json
import requests

from clinical_parser import parse_clinical_text
def is_gemini_configured() -> bool:
    key = os.getenv('GEMINI_API_KEY')
    return bool(key and key.strip() and key != 'your_gemini_api_key_here')

def process_medical_text(text: str, doc_type: str = 'other', patient_profile: dict = None) -> dict:
    if not is_gemini_configured():
        res = parse_clinical_text(text, doc_type, patient_profile)
        res['summary']['generatedBy'] = 'local-python-heuristics (Demo Mode)'
        return res

    api_key = os.getenv('GEMINI_API_KEY').strip()
    model_name = os.getenv('GEMINI_MODEL', 'gemini-2.5-flash')
    url = f"https://generativelanguage.googleapis.com/v1beta/models/{model_name}:generateContent?key={api_key}"

    prompt = f"""You are a specialized clinical data structuring AI assistant for "Personal Health Copilot".
Analyze the following healthcare document text and extract structured FHIR-inspired clinical entities.

CRITICAL RULES:
1. STRICT TRUTHFULNESS: Never invent missing values, diagnoses, dosages, or reference ranges.
2. REFERENCE RANGES: For lab tests, compare values against reference ranges. Classify as "NORMAL", "HIGH", "LOW", or "OUT_OF_RANGE".
3. MULTILINGUAL SUPPORT: Provide plain-language explanations in BOTH English and natural Hindi (सरल हिंदी).
4. SAFETY: Do not provide a diagnosis; frame outputs as educational summaries.

Input Document Text:
\"\"\"
{text}
\"\"\"

Return ONLY valid JSON matching this schema:
{{
  "title": "String",
  "documentType": "lab_report | prescription | discharge_summary | diagnostic_report | other",
  "documentDate": "YYYY-MM-DD",
  "facility": "String",
  "provider": "String",
  "confidenceScore": 85,
  "observations": [
    {{
      "id": "obs-1",
      "testName": "String",
      "value": "String",
      "unit": "String",
      "referenceRangeLow": "String",
      "referenceRangeHigh": "String",
      "referenceRangeText": "String",
      "interpretation": "NORMAL | HIGH | LOW | OUT_OF_RANGE",
      "explanation": "String",
      "needsReview": false
    }}
  ],
  "medications": [
    {{
      "id": "med-1",
      "name": "String",
      "strength": "String",
      "dosage": "String",
      "route": "Oral",
      "frequency": "String",
      "duration": "String",
      "instructions": "String",
      "indication": "String",
      "isActive": true,
      "needsReview": false
    }}
  ],
  "conditions": [
    {{
      "id": "cond-1",
      "name": "String",
      "status": "active",
      "notes": "String",
      "needsReview": false
    }}
  ],
  "allergies": [
    {{
      "id": "alg-1",
      "substance": "String",
      "reaction": "String",
      "severity": "moderate",
      "needsReview": false
    }}
  ],
  "encounter": {{
    "serviceType": "String",
    "providerName": "String",
    "facilityName": "String",
    "visitDate": "YYYY-MM-DD",
    "followUpInstructions": "String"
  }},
  "summary": {{
    "plainLanguageSummary": "English summary",
    "hindiSummary": "हिंदी सारांश",
    "keyTakeaways": ["point 1"],
    "questionsForDoctor": ["question 1"],
    "outOfRangeExplanations": [],
    "disclaimer": "This summary is generated by AI to help you understand your medical records. It is NOT medical advice."
  }}
}}"""

    try:
        response = requests.post(
            url,
            json={
                "contents": [{"parts": [{"text": prompt}]}],
                "generationConfig": {
                    "temperature": 0.1,
                    "responseMimeType": "application/json"
                }
            },
            timeout=15
        )
        if response.status_code == 200:
            data = response.json()
            candidate_text = data['candidates'][0]['content']['parts'][0]['text']
            clean_json = candidate_text.strip().removeprefix('```json').removesuffix('```').strip()
            parsed = json.loads(clean_json)
            parsed['rawText'] = text
            parsed['summary']['generatedBy'] = f"Gemini ({model_name})"
            return parsed
    except Exception as e:
        print(f"[Gemini Service Error] {e}. Falling back to deterministic parser.")

    res = parse_clinical_text(text, doc_type, patient_profile)
    res['summary']['generatedBy'] = 'local-python-heuristics (Fallback)'
    return res